/* KPI grid */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
  margin-bottom: var(--space-2xl);
}

.kpi-tile {
  background: var(--canvas);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  transition: box-shadow 200ms ease;
}

.kpi-tile:hover { box-shadow: var(--shadow-hover); }

.kpi-label {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}

.kpi-value {
  font-size: 36px;
  font-weight: 600;
  letter-spacing: -0.03em;
  font-family: var(--font-mono);
  line-height: 1;
}

.kpi-delta {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-mono);
}

.kpi-delta.positive { color: var(--success-text); }
.kpi-delta.negative { color: var(--error-text); }

.kpi-context {
  font-size: 12px;
  color: var(--text-tertiary);
}

/* Bento sections */
.section {
  margin-bottom: var(--space-2xl);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.section-title {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0;
}

.section-note {
  font-size: 13px;
  color: var(--text-secondary);
}

.bento {
  display: grid;
  gap: var(--space-lg);
}

.bento-3 { grid-template-columns: repeat(3, 1fr); }
.bento-2 { grid-template-columns: repeat(2, 1fr); }
.bento-mixed {
  grid-template-columns: 2fr 1fr;
}

.card {
  background: var(--canvas);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: var(--space-lg);
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  margin: 0 0 var(--space-md);
  color: var(--text);
}

.bar-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.bar-item {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: var(--space-md);
  align-items: center;
}

.bar-label {
  font-size: 13px;
  color: var(--text);
  font-weight: 500;
}

.bar-value {
  font-size: 13px;
  font-family: var(--font-mono);
  color: var(--text-secondary);
  text-align: right;
}

.bar-track {
  grid-column: 1 / -1;
  height: 6px;
  background: var(--bone);
  border-radius: 9999px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 9999px;
}

.bar-fill.muted { background: var(--text-tertiary); opacity: 0.5; }

/* Table */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.data-table th {
  text-align: left;
  padding: 10px 12px;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.data-table td {
  padding: 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text);
}

.data-table tr:last-child td { border-bottom: none; }

/* Status badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-success { background: var(--success-bg); color: var(--success-text); }
.badge-warning { background: var(--warning-bg); color: var(--warning-text); }
.badge-error { background: var(--error-bg); color: var(--error-text); }
.badge-info { background: var(--info-bg); color: var(--info-text); }

/* Funnel */
.funnel {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.funnel-row {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: var(--space-md);
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.funnel-row:last-child { border-bottom: none; }

.funnel-stage {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.funnel-bar {
  height: 8px;
  background: var(--accent);
  border-radius: 9999px;
  min-width: 4px;
}

.funnel-label {
  font-size: 13px;
  color: var(--text);
}

.funnel-count {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 600;
}

/* Activity */
.activity-list {
  display: flex;
  flex-direction: column;
}

.activity-row {
  display: grid;
  grid-template-columns: 130px 1fr auto;
  gap: var(--space-md);
  align-items: flex-start;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.activity-row:last-child { border-bottom: none; }

.activity-time {
  font-size: 12px;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  padding-top: 2px;
}

.activity-text {
  font-size: 13px;
  color: var(--text);
  line-height: 1.5;
}

.activity-text strong {
  font-weight: 600;
  color: var(--text);
}

.activity-meta {
  font-size: 12px;
  color: var(--text-secondary);
  font-family: var(--font-mono);
}

/* Empty state */
.empty-state {
  padding: var(--space-2xl);
  text-align: center;
  color: var(--text-secondary);
}

.empty-state-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: var(--space-sm);
}

/* Mobile nav toggle */
.mobile-nav-toggle {
  display: none;
  position: fixed;
  top: var(--space-md);
  left: var(--space-md);
  z-index: 100;
  width: 44px;
  height: 44px;
  border: 1px solid var(--border);
  background: var(--canvas);
  border-radius: var(--radius-sm);
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

    }

    /* Reduced motion */
    @media (prefers-reduced-motion: reduce) {
      * { animation: none !important; transition: none !important; }
    }

    /* Responsive */
    @media (max-width: 1200px) {
      .kpi-grid { grid-template-columns: repeat(2, 1fr); }
      .bento-3 { grid-template-columns: repeat(2, 1fr); }
      .bento-mixed { grid-template-columns: 1fr; }
    }

    @media (max-width: 1024px) {
      .app { grid-template-columns: 1fr; }
      .sidebar {
        position: fixed;
        left: 0;
        top: 0;
        z-index: 90;
        transform: translateX(-100%);
        transition: transform 250ms ease;
        box-shadow: 4px 0 24px rgba(0,0,0,0.08);
      }
      .sidebar.is-open { transform: translateX(0); }
      .mobile-nav-toggle { display: flex; }
      .main { padding: var(--space-xl); padding-top: 72px; }
      .page-header { flex-direction: column; }
      .filter-meta { margin-left: 0; }
    }

    @media (max-width: 768px) {
      .kpi-grid,
      .bento-3,
      .bento-2,
      .bento-mixed { grid-template-columns: 1fr; }
      .filter-bar { flex-direction: column; align-items: stretch; }
      .filter-group { min-width: auto; }
      .filter-meta { justify-content: space-between; }
      .activity-row {
        grid-template-columns: 1fr;
        gap: var(--space-xs);
      }
      .activity-meta { text-align: left; }
    }

    /* Entrance animation */
    @keyframes enter {
      from { opacity: 0; transform: translateY(12px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .animate-enter {
      animation: enter 600ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .delay-1 { animation-delay: 80ms; }
    .delay-2 { animation-delay: 160ms; }
    .delay-3 { animation-delay: 240ms; }
    .delay-4 { animation-delay: 320ms; }
  </style>
