    <div class="modal">
      <h3 class="modal-title" id="funnel-title">Application Funnel</h3>
      <p class="modal-desc" id="funnel-desc">Job Details: Textile Production Supervisor at Highland Textile Works</p>

      <div class="privacy-box">
        <i class="ph-bold ph-shield-check"></i>
        <span>Individual applicant identities are masked in accordance with Alliance data privacy controls.</span>
      </div>

      <h4 style="font-size: 13px; font-weight:600; margin-bottom:8px;">Pipeline Status:</h4>
      <div class="funnel-list" id="funnel-applicants-box">
        <!-- Applicants show up here masked -->
      </div>

      <div class="modal-actions">
        <button class="btn btn-primary" onclick="closeModal()">Close Details</button>
      </div>
    </div>
  </div>

  <script>
    /* i18n:STR:start */
    const STR = {
      funnelTitle: "{jobTitle} Funnel",
      funnelDesc: "{jobTitle} at {entity} ({count} applicants total)",
      applicantCandidate: "Applicant #C-098{id}",
      stageHired: "Hired",
      stageOfferAccepted: "Offer Accepted",
      stageShortlisted: "Shortlisted",
      stageBackgroundCheck: "Background check",
      stageCallScreening: "Call screening",
      stageQualified: "Qualified",
      stageNewApplicant: "New applicant",
      moreApplicants: "... and {count} more applicants in earlier stages."
    };
    /* i18n:STR:end */
    const fmt = (s, v = {}) => s.replace(/\{(\w+)\}/g, (_, k) => v[k] ?? '{' + k + '}');

    function openModal(id) {
      document.getElementById(id).classList.add('is-open');
    }

    function closeModal() {
      document.getElementById('funnel-modal').classList.remove('is-open');
    }

    function filterJobs() {
      const entity = document.getElementById('filter-entity').value.toLowerCase();
      const sector = document.getElementById('filter-sector').value.toLowerCase();
      const status = document.getElementById('filter-status').value.toLowerCase();
      const rows = document.querySelectorAll('#jobs-table tbody tr');

      rows.forEach(row => {
        const rowEntity = row.getAttribute('data-entity').toLowerCase();
        const rowSector = row.getAttribute('data-sector').toLowerCase();
        const rowStatus = row.getAttribute('data-status').toLowerCase();

        const matchEntity = (entity === 'all' || rowEntity === entity);
        const matchSector = (sector === 'all' || rowSector === sector);
        const matchStatus = (status === 'all' || rowStatus === status);

        if(matchEntity && matchSector && matchStatus) {
          row.style.display = '';
        } else {
          row.style.display = 'none';
        }
      });
    }

    function viewFunnel(jobTitle, entity, count) {
      document.getElementById('funnel-title').textContent = fmt(STR.funnelTitle, { jobTitle });
      document.getElementById('funnel-desc').textContent = fmt(STR.funnelDesc, { jobTitle, entity, count });

      const box = document.getElementById('funnel-applicants-box');
      box.innerHTML = '';

      const stages = [
        STR.stageHired,
        STR.stageOfferAccepted,
        STR.stageShortlisted,
        STR.stageBackgroundCheck,
        STR.stageCallScreening,
        STR.stageQualified,
        STR.stageNewApplicant
      ];

      // Generate mock applicants masked
      for(let i = 1; i <= Math.min(count, 5); i++) {
        const stage = stages[Math.min(i - 1, stages.length - 1)];
        const item = document.createElement('div');
        item.className = 'funnel-item';
        item.innerHTML = `
          <span class="funnel-candidate">${fmt(STR.applicantCandidate, { id: i + 4 })}</span>
          <span class="badge ${stage === STR.stageHired ? 'badge-success' : 'badge-warning'}">${stage}</span>
        `;
        box.appendChild(item);
      }

      if(count > 5) {
        const more = document.createElement('div');
        more.style.fontSize = '12px';
        more.style.color = 'var(--text-secondary)';
        more.style.textAlign = 'center';
        more.style.marginTop = '8px';
        more.textContent = fmt(STR.moreApplicants, { count: count - 5 });
        box.appendChild(more);
      }

      openModal('funnel-modal');
    }
  </script>
</body>
</html>

